import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { FHIRObservation, ClinicalDataStore } from '../../fhir/types';
import { CDSSAlert } from '../../cdss/types';
import { indexedDBStorage } from '../../../services/storage';

interface ClinicalState {
    data: Record<string, ClinicalDataStore>;
    alerts: Record<string, CDSSAlert[]>;
    // Tracks when a specific Rule ID was last dismissed for a patient
    // Structure: { [patientId]: { [ruleId]: timestamp } }
    dismissalHistory: Record<string, Record<string, number>>;
}

interface ClinicalActions {
    actions: {
        initializePatient: (patientId: string) => void;
        deletePatient: (patientId: string) => void;

        ingestObservations: (patientId: string, observations: FHIRObservation[]) => void;
        updateAlerts: (patientId: string, alerts: CDSSAlert[]) => void;
        dismissAlert: (patientId: string, alertId: string, ruleId: string) => void;
    }
}

// Duration to suppress a dismissed alert (e.g., 6 hours)
const ALERT_SUPPRESSION_MS = 6 * 60 * 60 * 1000;

export const useClinicalStore = create<ClinicalState & ClinicalActions>()(
    persist(
        (set, get) => ({
            data: {},
            alerts: {},
            dismissalHistory: {},

            actions: {
                initializePatient: (patientId) => set((state) => {
                    if (state.data[patientId]) return state;
                    return {
                        data: { ...state.data, [patientId]: { observations: [] } },
                        alerts: { ...state.alerts, [patientId]: [] },
                        dismissalHistory: { ...state.dismissalHistory, [patientId]: {} }
                    };
                }),
                deletePatient: (patientId) => set((state) => {
                    const newData = { ...state.data };
                    const newAlerts = { ...state.alerts };
                    const newHistory = { ...state.dismissalHistory };

                    delete newData[patientId];
                    delete newAlerts[patientId];
                    delete newHistory[patientId];

                    return { data: newData, alerts: newAlerts, dismissalHistory: newHistory };
                }),

                ingestObservations: (patientId, observations) => set((state) => {
                    const currentStore = state.data[patientId] || { observations: [] };
                    const existingObs = currentStore.observations;

                    // Deduplication Logic
                    const newObs = observations.filter(obs => 
                        !existingObs.some(ex => 
                            ex.code.text === obs.code.text && 
                            ex.valueQuantity?.value === obs.valueQuantity?.value &&
                            ex.effectiveDateTime === obs.effectiveDateTime
                        )
                    );

                    return {
                        data: {
                            ...state.data,
                            [patientId]: {
                                ...currentStore,
                                observations: [...existingObs, ...newObs]
                            }
                        }
                    };
                }),

                updateAlerts: (patientId, incomingAlerts) => set((state) => {
                    const currentAlerts = state.alerts[patientId] || [];
                    const patientHistory = state.dismissalHistory[patientId] || {};
                    const now = Date.now();

                    // Filter 1: Remove alerts that are currently active (prevent duplicate entries of same alert)
                    // Filter 2: Remove alerts that were dismissed recently (Cooldown check)
                    const newAlerts = incomingAlerts.filter(na => {
                        const isAlreadyActive = currentAlerts.some(ca => ca.ruleId === na.ruleId);
                        if (isAlreadyActive) return false;

                        const lastDismissed = patientHistory[na.ruleId];
                        if (lastDismissed && (now - lastDismissed < ALERT_SUPPRESSION_MS)) {
                            // Suppress this alert
                            return false;
                        }
                        return true;
                    });

                    if (newAlerts.length === 0) return state;

                    return {
                        alerts: {
                            ...state.alerts,
                            [patientId]: [...currentAlerts, ...newAlerts]
                        }
                    };
                }),

                dismissAlert: (patientId, alertId, ruleId) => set((state) => {
                    const currentAlerts = state.alerts[patientId] || [];
                    const patientHistory = state.dismissalHistory[patientId] || {};

                    return {
                        alerts: {
                            ...state.alerts,
                            [patientId]: currentAlerts.filter(a => a.id !== alertId)
                        },
                        dismissalHistory: {
                            ...state.dismissalHistory,
                            [patientId]: {
                                ...patientHistory,
                                [ruleId]: Date.now() // Record dismissal time
                            }
                        }
                    };
                })
            }
        }),
        {
            name: 'medibrief-clinical-storage',
            storage: createJSONStorage(() => indexedDBStorage),
            skipHydration: true, // WAIT FOR SECURITY GATE
        }
    )
);

import React from 'react';
import { usePatientStore } from '../patient-management/usePatientStore';
import { useClinicalStore } from '../clinical-analysis/stores/useClinicalStore';
import { useChatStore } from '../chat/stores/useChatStore';
import { useAuditStore } from '../audit/useAuditStore';
import InterventionCard from './InterventionCard';
import CDSSAggregator from './CDSSAggregator';
import { CDSSAlert } from './types';

const CDSSContainer: React.FC = () => {
    const activePatientId = usePatientStore(state => state.activePatientId);

    // Select Alerts from Clinical Store
    const activeAlerts = useClinicalStore(state => state.alerts[activePatientId] || []);
    const clinicalActions = useClinicalStore(state => state.actions);
    const chatActions = useChatStore(state => state.actions);
    const auditActions = useAuditStore(state => state.actions);

    if (activeAlerts.length === 0) return null;

    const handleAction = (alert: CDSSAlert, actionIndex: number) => {
        const action = alert.actions[actionIndex];

        if (action.type === 'dismiss') {
            // Updated: Pass ruleId to enable suppression logic
            clinicalActions.dismissAlert(activePatientId, alert.id, alert.ruleId);
            auditActions.logEvent(
                'ALERT_DISMISSED', 
                activePatientId, 
                `Dismissed alert: ${alert.title}`, 
                'USER',
                { ruleId: alert.ruleId, alertLevel: alert.level }
            );
        } else if (action.type === 'order' || action.type === 'acknowledge') {
            // Inject the action into the chat as a system note or user action
            if (action.payload) {
                chatActions.addMessage(activePatientId, { 
                    role: 'model', 
                    content: `✅ **ACTION EXECUTED**: ${action.payload}\n\n*Protocol: ${alert.title}*` 
                });
            }
            // Acknowledge implies dismissal/resolution
            clinicalActions.dismissAlert(activePatientId, alert.id, alert.ruleId);

            auditActions.logEvent(
                'ALERT_ACTION',
                activePatientId,
                `Executed action "${action.label}" for alert: ${alert.title}`,
                'USER',
                { ruleId: alert.ruleId, actionType: action.type, payload: action.payload }
            );
        }
    };

    // Filter alerts into visibility tiers
    const criticalAlerts = activeAlerts.filter(a => a.level === 'Critical');
    const standardAlerts = activeAlerts.filter(a => a.level !== 'Critical');

    return (
        <>
            {/* TIER 1: CRITICAL INTERVENTION LAYER (BLOCKING OVERLAY) */}
            {/* Sits on top of everything except the absolute header, dims the chat content */}
            {criticalAlerts.length > 0 && (
                <div className="fixed inset-0 z-[60] flex items-start justify-center pt-20 md:pt-32 bg-slate-900/40 backdrop-blur-[3px] pointer-events-auto px-4 pb-4 overflow-y-auto animate-fade-in">
                    <div className="w-full max-w-3xl flex flex-col gap-4">
                        {criticalAlerts.map(alert => (
                            <InterventionCard 
                                key={alert.id} 
                                alert={alert} 
                                onAction={handleAction} 
                                variant="banner"
                            />
                        ))}
                    </div>
                </div>
            )}

            {/* TIER 2: STANDARD NOTIFICATION LAYER (BOTTOM RIGHT TOASTS) */}
            {/* Non-intrusive updates for warnings and info */}
            {standardAlerts.length > 0 && (
                <div className="absolute bottom-4 right-4 z-40 flex flex-col items-end pointer-events-none w-full max-w-sm px-4 md:px-0">
                    <div className="pointer-events-auto w-full">
                        {standardAlerts.length > 1 ? (
                            <CDSSAggregator 
                                alerts={standardAlerts}
                                onAction={handleAction}
                            />
                        ) : (
                            <InterventionCard 
                                key={standardAlerts[0].id} 
                                alert={standardAlerts[0]} 
                                onAction={handleAction}
                                variant="toast" 
                            />
                        )}
                    </div>
                </div>
            )}
        </>
    );
};

export default CDSSContainer;

import React, { useState, useRef } from 'react';
import { usePatientStore } from '../patient-management/usePatientStore';
import { useChatStore } from '../chat/stores/useChatStore';
import { useClinicalStore } from '../clinical-analysis/stores/useClinicalStore';
import { blobStorage } from '../../services/blobStorageService';
import PatientCard from './PatientCard';
import AddPatientDialog from './AddPatientDialog';
import { ChevronLeftIcon, UsersIcon, DownloadIcon, ClipboardIcon, PlusIcon } from '../../components/icons';
import { useToast } from '../../components/Toast';
import { PatientMetadata, FullPatientContext, PatientDemographics } from '../patient-management/types';
import { BackupFileSchema } from '../chat/schemas';

interface SidebarRosterProps {
    isOpen: boolean;
    toggle: () => void;
}

const SidebarRoster: React.FC<SidebarRosterProps> = ({ isOpen, toggle }) => {
    // Zustand Selectors
    const { patients, activePatientId, actions } = usePatientStore(state => ({
        patients: state.patients,
        activePatientId: state.activePatientId,
        actions: state.actions
    }));

    // Access other store actions for CRUD sync
    const chatActions = useChatStore(state => state.actions);
    const clinicalActions = useClinicalStore(state => state.actions);

    const { showToast } = useToast();
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const patientsList = (Object.values(patients) as PatientMetadata[]).sort((a, b) => b.lastActive - a.lastActive);

    const handleSwitch = (id: string) => {
        actions.switchPatient(id);
    };

    const handleDelete = async (id: string, name: string) => {
        if (Object.keys(patients).length <= 1) {
            showToast("Cannot delete the only active patient context.", 'error');
            return;
        }

        if (confirm(`Are you sure you want to delete the context for "${name}"?\nThis action cannot be undone.`)) {
             // 1. Clean up heavy assets in IndexedDB
             const patient = patients[id];
             if (patient && patient.documents) {
                 let deletedCount = 0;
                 for (const doc of patient.documents) {
                     if (doc.storageId) {
                         try {
                             await blobStorage.deleteFile(doc.storageId);
                             deletedCount++;
                         } catch (e) {
                             console.warn("Failed to delete file asset:", doc.storageId);
                         }
                     }
                 }
                 if (deletedCount > 0) console.log(`Cleaned up ${deletedCount} assets for deleted patient.`);
             }

             // 2. Clear Stores
             actions.deletePatient(id);
             chatActions.deleteChat(id);
             clinicalActions.deletePatient(id);
             showToast(`Patient context deleted`, 'info');
        }
    };

    const handleCreate = (name: string, demographics: PatientDemographics) => {
        const newId = actions.createPatient(name, demographics);
        chatActions.initializeChat(newId);
        clinicalActions.initializePatient(newId);
        setIsDialogOpen(false);
        showToast(`Patient context '${name}' initialized`, 'success');
    };

    const handleExportData = () => {
        try {
            const chatState = useChatStore.getState().chats;
            const clinicalState = useClinicalStore.getState().data;
            const alertsState = useClinicalStore.getState().alerts;

            // Construct composite export object
            const exportData: Record<string, FullPatientContext> = {};
            Object.keys(patients).forEach(id => {
                exportData[id] = {
                    ...patients[id],
                    chatHistory: chatState[id] || [],
                    clinicalData: clinicalState[id] || { observations: [] },
                    activeAlerts: alertsState[id] || []
                };
            });

            const payload = { 
                version: '4.2', 
                patients: exportData, 
                activePatientId 
            };

            const dataStr = JSON.stringify(payload);
            const blob = new Blob([dataStr], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `medibrief-backup-${new Date().toISOString().split('T')[0]}.json`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
            showToast('System backup downloaded successfully', 'success');
        } catch (e) {
            showToast('Failed to export system data', 'error');
        }
    };

    const handleImportClick = () => {
        fileInputRef.current?.click();
    };

    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            try {
                const rawJson = event.target?.result as string;
                const imported = JSON.parse(rawJson);

                // --- SECURITY VALIDATION (Risk C Fix) ---
                // Validate schema before any hydration to prevent state poisoning
                const validationResult = BackupFileSchema.safeParse(imported);

                if (!validationResult.success) {
                    console.error("Schema Validation Errors:", validationResult.error);
                    throw new Error("Corrupted or malicious file structure.");
                }

                const validData = validationResult.data;

                if (validData && validData.patients) {
                    // Deconstruct and distribute to stores
                    const patientMeta: Record<string, PatientMetadata> = {};

                    Object.keys(validData.patients).forEach(id => {
                        const full = validData.patients[id] as FullPatientContext;

                        // 1. Meta Store
                        patientMeta[id] = {
                            id: full.id,
                            name: full.name,
                            status: full.status,
                            entities: full.entities,
                            demographics: full.demographics || {},
                            documents: full.documents,
                            createdAt: full.createdAt,
                            lastActive: full.lastActive
                        };

                        // 2. Chat Store
                        useChatStore.setState(state => ({
                            chats: { ...state.chats, [id]: full.chatHistory || [] }
                        }));

                        // 3. Clinical Store
                        useClinicalStore.setState(state => ({
                            data: { ...state.data, [id]: full.clinicalData || { observations: [] } },
                            alerts: { ...state.alerts, [id]: full.activeAlerts || [] }
                        }));
                    });

                    actions.setAllPatients(patientMeta, validData.activePatientId || Object.keys(patientMeta)[0]);

                    showToast('System state restored successfully.', 'success');
                } else {
                    throw new Error("Invalid format");
                }
            } catch (error: any) {
                console.error(error);
                showToast(`Import Failed: ${error.message}`, 'error');
            }
        };
        reader.readAsText(file);
        e.target.value = ''; // Reset input
